export type DiscountRule = {
  id: number;
  name: string;
  defaultDiscount: number | "--" | "";
  status: DiscountStatus;
  note: string;
  refundRule: RefundRule;
  studentCount: number;
};
export type StudentDiscount = {
  id: number;
  name: string;
  studentNo: string;
  phone: string;
  ruleId: number | null;
  discount: number | "";
  start: string;
  end: string;
  attribute: string;
  courses: string[];
  classes: string[];
  note: string;
  status: DiscountStatus;
};

