function ScopePicker({ form, setForm }: { form: StudentDiscount; setForm: React.Dispatch<React.SetStateAction<StudentDiscount>> }) {
  const [open, setOpen] = useState(false);
  const [courses, setCourses] = useState(form.courses);
  const [classes, setClasses] = useState(form.classes);
  const selectedText = [...form.courses, ...form.classes].join("、");
  const toggle = (values: string[], value: string, setter: React.Dispatch<React.SetStateAction<string[]>>) => setter(values.includes(value) ? values.filter((item) => item !== value) : [...values, value]);
  return <><label className="block"><span className="mb-2 block text-sm font-semibold text-[#344054]">适用课程或班级范围</span><button type="button" onClick={() => { setCourses(form.courses); setClasses(form.classes); setOpen(true); }} className="flex min-h-11 w-full items-center justify-between rounded-lg border border-[#dbe3ef] px-3 text-left text-sm text-[#344054] hover:border-[#165dff]"><span className={selectedText ? "truncate" : "text-[#98a2b3]"}>{selectedText || "请选择课程或班级"}</span><span className="text-[#667085]">选择</span></button></label>{open && <div className="fixed inset-0 z-[95] flex items-center justify-center bg-[#101828]/45 px-4" onClick={() => setOpen(false)}><div className="w-full max-w-[760px] rounded-2xl bg-white shadow-2xl" onClick={(event) => event.stopPropagation()}><header className="flex items-center justify-between border-b border-[#e5e9f0] px-6 py-4"><h3 className="text-lg font-semibold text-[#1d2939]">选择适用课程或班级</h3><button type="button" onClick={() => setOpen(false)} className="rounded-lg p-2 text-[#667085] hover:bg-[#f2f4f7]"><X size={20} /></button></header><div className="grid gap-5 p-6 sm:grid-cols-2"><div><p className="mb-2 text-sm font-semibold text-[#344054]">课程（可多选）</p><div className="max-h-56 space-y-2 overflow-y-auto rounded-lg border border-[#dbe3ef] p-3">{COURSE_OPTIONS.map((item) => <label key={item} className="flex cursor-pointer items-start gap-2 rounded-md px-2 py-2 text-sm text-[#344054] hover:bg-[#f8fafc]"><input type="checkbox" checked={courses.includes(item)} onChange={() => toggle(courses, item, setCourses)} className="mt-0.5 accent-[#165dff]" />{item}</label>)}</div></div><div><p className="mb-2 text-sm font-semibold text-[#344054]">班级（可多选）</p><div className="max-h-56 space-y-2 overflow-y-auto rounded-lg border border-[#dbe3ef] p-3">{CLASS_OPTIONS.map((item) => <label key={item} className="flex cursor-pointer items-start gap-2 rounded-md px-2 py-2 text-sm text-[#344054] hover:bg-[#f8fafc]"><input type="checkbox" checked={classes.includes(item)} onChange={() => toggle(classes, item, setClasses)} className="mt-0.5 accent-[#165dff]" />{item}</label>)}</div></div></div><footer className="flex justify-end gap-3 border-t border-[#e5e9f0] px-6 py-4"><button type="button" onClick={() => setOpen(false)} className="rounded-lg border border-[#dbe3ef] px-5 py-2.5 text-sm font-semibold text-[#667085]">取消</button><button type="button" onClick={() => { setForm((current) => ({ ...current, courses, classes })); setOpen(false); }} className="rounded-lg bg-[#18234b] px-5 py-2.5 text-sm font-semibold text-white">确认选择</button></footer></div></div>}</>;
}

function StudentDiscountFieldsScope({ form, setForm, rules }: { form: StudentDiscount; setForm: React.Dispatch<React.SetStateAction<StudentDiscount>>; rules: DiscountRule[] }) {
  const update = <K extends keyof StudentDiscount>(key: K, value: StudentDiscount[K]) => setForm((current) => ({ ...current, [key]: value }));
  const selectedRule = rules.find((item) => item.id === form.ruleId);
  return <div className="space-y-4"><label className="block"><span className="mb-2 block text-sm font-semibold text-[#344054]">折扣规则 <em className="text-[#c84d3c]">*</em></span><select required value={form.ruleId ?? ""} onChange={(event) => { const nextRule = rules.find((item) => item.id === Number(event.target.value)); setForm((current) => ({ ...current, ruleId: nextRule?.id ?? null, discount: typeof nextRule?.defaultDiscount === "number" ? nextRule.defaultDiscount : "" })); }} className="h-11 w-full rounded-lg border border-[#dbe3ef] px-3 text-sm"><option value="">请选择折扣规则</option>{rules.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="block"><span className="mb-2 flex items-center gap-3 text-sm font-semibold text-[#344054]">折扣比例 <em className="text-xs font-normal not-italic text-[#b7791f]">默认取折扣规则的比例，支持手动修改</em></span><div className="relative"><input required type="number" min="0" max="100" value={form.discount} onChange={(event) => update("discount", event.target.value === "" ? "" : Number(event.target.value))} className="h-11 w-full rounded-lg border border-[#e7b84b] bg-[#fff8e1] px-3 pr-10 text-sm font-semibold text-[#9a6700] outline-none focus:border-[#c98a00] focus:ring-2 focus:ring-[#f5d98b]" /><span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 font-semibold text-[#b7791f]">%</span></div></label><ScopePicker form={form} setForm={setForm} /><div className="grid gap-4 sm:grid-cols-2"><label><span className="mb-2 block text-sm font-semibold text-[#344054]">开始时间</span><input required type="datetime-local" step="1" value={form.start} onChange={(event) => update("start", event.target.value)} className="h-11 w-full rounded-lg border border-[#dbe3ef] px-3 text-sm" /></label><label><span className="mb-2 block text-sm font-semibold text-[#344054]">结束时间</span><input required type="datetime-local" step="1" value={form.end} onChange={(event) => update("end", event.target.value)} className="h-11 w-full rounded-lg border border-[#dbe3ef] px-3 text-sm" /></label></div><label><span className="mb-2 block text-sm font-semibold text-[#344054]">备注信息</span><textarea value={form.note} onChange={(event) => update("note", event.target.value)} placeholder="请输入备注信息" className="min-h-24 w-full rounded-lg border border-[#dbe3ef] px-3 py-2 text-sm" /></label><div className="rounded-lg bg-[#f8fafc] px-3 py-2 text-xs text-[#667085]">当前规则：{selectedRule?.name ?? "未选择"}，折扣比例 {form.discount === "" ? "" : String(form.discount) + "%"}</div><ApprovalFlow /></div>;
}

export function StudentDrawerV2({ student, rules, onSave, onClose }: { student: StudentDiscount | null; rules: DiscountRule[]; onSave: (student: StudentDiscount) => void; onClose: () => void }) {
  const [mode, setMode] = useState<"manual" | "batch">("manual");
  const [availableRules, setAvailableRules] = useState(rules);
  const [newRuleDrawer, setNewRuleDrawer] = useState<DiscountRule | null | undefined>(undefined);
  const [form, setForm] = useState<StudentDiscount>(student ?? { id: Date.now(), name: "", studentNo: "", phone: "", ruleId: null, discount: "", start: "", end: "", attribute: COURSE_ATTRIBUTES[0], courses: [], classes: [], note: "", status: "启用中" });
  const canSubmit = form.ruleId !== null && form.discount !== "" && (mode === "batch" || (form.name && form.studentNo));
  const saveNewRule = (rule: DiscountRule) => { const created = { ...rule, id: Math.max(...availableRules.map((item) => item.id), 0) + 1 }; setAvailableRules((current) => [...current, created]); setNewRuleDrawer(undefined); };

  return <><DrawerShell title={student ? "编辑学员折扣" : "新增学员折扣"} onClose={onClose} width="max-w-[820px]" footer={<><button onClick={onClose} className="rounded-lg border border-[#dbe3ef] px-5 py-2.5 text-sm font-semibold text-[#667085]">取消</button><button disabled={!canSubmit} onClick={() => { if (canSubmit) onSave(form); }} className="rounded-lg bg-[#18234b] px-5 py-2.5 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:opacity-40">提交审批</button></>}>
    <div className="space-y-5">
      <div className="flex rounded-xl bg-[#f5f7fb] p-1">
        <button type="button" onClick={() => setMode("manual")} className={`flex-1 rounded-lg px-4 py-2.5 text-sm font-semibold ${mode === "manual" ? "bg-white text-[#165dff] shadow-sm" : "text-[#667085]"}`}>手动选择学员</button>
        <button type="button" onClick={() => setMode("batch")} className={`flex-1 rounded-lg px-4 py-2.5 text-sm font-semibold ${mode === "batch" ? "bg-white text-[#165dff] shadow-sm" : "text-[#667085]"}`}>批量导入学员</button>
      </div>
      {mode === "batch" ? <BatchStudentUpload /> : <StudentLookup form={form} setForm={setForm} />}
      <div className="relative"><button type="button" onClick={() => setNewRuleDrawer(null)} className="absolute right-0 top-0 z-10 rounded-lg border border-[#165dff] px-3 py-1.5 text-xs font-semibold text-[#165dff] hover:bg-[#eef4ff]">新建折扣规则</button><StudentDiscountFieldsScope form={form} setForm={setForm} rules={availableRules} /></div>
    </div>
  </DrawerShell>{newRuleDrawer !== undefined && <RuleDrawer rule={newRuleDrawer} onSave={saveNewRule} onClose={() => setNewRuleDrawer(undefined)} />}</>;
}

export function PersonalDiscountPage({ onBack, onOpenActivity }: { onBack: () => void; onOpenActivity: () => void }) {
  const [tab, setTab] = useState<"rules" | "students">("students");
  const [rules, setRules] = useState(initialRules);
  const [students, setStudents] = useState(initialStudents);
  const [ruleDrawer, setRuleDrawer] = useState<DiscountRule | null | undefined>(undefined);
  const [studentDrawer, setStudentDrawer] = useState<StudentDiscount | null | undefined>(undefined);
  const [detailRule, setDetailRule] = useState<DiscountRule | null>(null);
  const [statusFilter, setStatusFilter] = useState<DiscountStatus[]>(["启用中"]);
  const [search, setSearch] = useState("");
  const [studentRuleFilter, setStudentRuleFilter] = useState<number | null>(null);
  const visibleRules = useMemo(() => rules.filter((item) => statusFilter.includes(item.status) && item.name.includes(search.trim())), [rules, statusFilter, search]);
  const visibleStudents = useMemo(() => students.filter((item) => (item.name.includes(search.trim()) || item.studentNo.includes(search.trim())) && (studentRuleFilter === null || item.ruleId === studentRuleFilter)), [students, search, studentRuleFilter]);
  const saveRule = (rule: DiscountRule) => { setRules((current) => current.some((item) => item.id === rule.id) ? current.map((item) => item.id === rule.id ? rule : item) : [{ ...rule, id: Math.max(...current.map((item) => item.id), 0) + 1 }, ...current]); setRuleDrawer(undefined); };
  const saveStudent = (student: StudentDiscount) => { setStudents((current) => current.some((item) => item.id === student.id) ? current.map((item) => item.id === student.id ? student : item) : [{ ...student, id: Math.max(...current.map((item) => item.id), 0) + 1 }, ...current]); setStudentDrawer(undefined); };
  const toggleRule = (id: number) => setRules((current) => current.map((item) => item.id === id ? { ...item, status: item.status === "启用中" ? "已停用" : "启用中" } : item));
  const toggleStudent = (id: number) => setStudents((current) => current.map((item) => item.id === id ? { ...item, status: item.status === "启用中" ? "已停用" : "启用中" } : item));
  const setSelectedIdsForLog = (id: number) => { const student = students.find((item) => item.id === id); setDetailRule(rules.find((item) => item.id === student?.ruleId) ?? null); };
  return <main className="min-h-screen bg-[#f5f7fb] px-2 py-5 text-[#182230] sm:px-3 lg:px-4"><div className="mx-auto max-w-[1800px] space-y-4"><header className="flex flex-col gap-4 rounded-2xl border border-[#e5e9f0] bg-white px-5 py-4 shadow-sm lg:flex-row lg:items-center lg:justify-between"><div className="flex items-center gap-4"><button onClick={onBack} className="rounded-lg border border-[#dbe3ef] px-3 py-2 text-sm font-semibold text-[#667085]">返回首页</button><div><h1 className="text-2xl font-semibold text-[#1d2939]">个人折扣配置</h1><p className="mt-1 text-sm text-[#667085]">配置折扣规则与学员专属折扣，提交变更后进入审批流程。</p></div></div><div className="flex flex-wrap gap-2"><button onClick={() => setRuleDrawer(null)} className="inline-flex items-center gap-2 rounded-lg bg-[#18234b] px-4 py-2.5 text-sm font-semibold text-white"><Plus size={16} />新增折扣规则</button><button onClick={() => setStudentDrawer(null)} className="inline-flex items-center gap-2 rounded-lg bg-[#165dff] px-4 py-2.5 text-sm font-semibold text-white shadow-sm"><Users size={16} />新增学员折扣 <span className="rounded-full bg-white/20 px-2 py-0.5 text-xs text-white">需审批</span></button></div></header><section className="rounded-2xl border border-[#e5e9f0] bg-white shadow-sm"><div className="flex flex-col gap-3 border-b border-[#edf0f4] px-5 pt-4 lg:flex-row lg:items-center lg:justify-between"><div className="flex gap-6"><button onClick={() => { setTab("students"); setStudentRuleFilter(null); }} className={`border-b-2 px-1 pb-3 text-sm font-semibold ${tab === "students" ? "border-[#165dff] text-[#165dff]" : "border-transparent text-[#667085]"}`}>学员明细</button><button onClick={() => setTab("rules")} className={`border-b-2 px-1 pb-3 text-sm font-semibold ${tab === "rules" ? "border-[#165dff] text-[#165dff]" : "border-transparent text-[#667085]"}`}>折扣规则</button></div><div className="flex flex-wrap gap-2 pb-3"><div className="relative"><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder={tab === "rules" ? "搜索规则名称" : "搜索姓名或学号"} className="h-10 w-60 rounded-lg border border-[#dbe3ef] px-3 text-sm outline-none focus:border-[#165dff]" /></div>{tab === "rules" && <select aria-label="折扣规则状态" value={statusFilter[0] ?? ""} onChange={(event) => setStatusFilter(event.target.value ? [event.target.value as DiscountStatus] : [])} className="h-10 rounded-lg border border-[#dbe3ef] px-3 text-sm text-[#344054]"><option value="">全部状态</option>{STATUS_OPTIONS.map((status) => <option key={status} value={status}>{status}</option>)}</select>}</div></div>{tab === "rules" ? <div className="overflow-x-auto"><table className="min-w-[1080px] w-full border-collapse text-sm"><thead className="bg-[#f8fafc] text-left text-[#667085]"><tr>{["规则名称", "默认折扣（%）", "学员数量", "状态", "备注说明", "退费规则", "操作"].map((title) => <th key={title} className="border-b border-[#e5e9f0] px-5 py-3 font-medium">{title}</th>)}</tr></thead><tbody>{visibleRules.map((item) => <tr key={item.id} className="border-b border-[#edf0f4] align-top hover:bg-[#fbfcff]"><td className="max-w-[300px] px-5 py-5 font-medium text-[#344054]">{item.name}</td><td className="px-5 py-5 text-[#344054]">{item.defaultDiscount}</td><td className="px-5 py-5 text-[#165dff]"><button onClick={() => { setStudentRuleFilter(item.id); setSearch(""); setTab("students"); }} className="font-medium hover:underline">{item.studentCount}</button></td><td className="px-5 py-5"><StatusBadge status={item.status} /></td><td className="max-w-[280px] px-5 py-5 text-[#667085]">{item.note || "—"}</td><td className="px-5 py-5 text-[#667085]">{item.refundRule}</td><td className="whitespace-nowrap px-5 py-5"><button onClick={() => toggleRule(item.id)} className={`mr-3 ${item.status === "启用中" ? "text-[#f04438]" : "text-[#165dff]"}`}>{item.status === "启用中" ? "停用" : "启用"}</button><button onClick={() => setRuleDrawer(item)} className="text-[#165dff]">编辑</button></td></tr>)}</tbody></table>{!visibleRules.length && <div className="px-6 py-16 text-center text-sm text-[#667085]">没有符合条件的折扣规则</div>}</div> : <div className="overflow-x-auto"><table className="min-w-[1450px] w-full border-collapse text-sm"><thead className="bg-[#f8fafc] text-left text-[#667085]"><tr>{["姓名", "学号", "手机号", "优惠规则", "折扣比例", "生效时间", "生效范围", "备注信息", "操作"].map((title) => <th key={title} className="border-b border-[#e5e9f0] px-4 py-3 font-medium">{title}</th>)}</tr></thead><tbody>{visibleStudents.map((item) => { const rule = rules.find((candidate) => candidate.id === item.ruleId); return <tr key={item.id} className="border-b border-[#edf0f4] align-top hover:bg-[#fbfcff]"><td className="px-4 py-5 font-medium text-[#344054]">{item.name}</td><td className="px-4 py-5 text-[#667085]">{item.studentNo}</td><td className="px-4 py-5 text-[#667085]">{item.phone}</td><td className="px-4 py-5"><button onClick={() => setDetailRule(rule ?? null)} className="max-w-[240px] truncate text-left text-[#165dff]">{rule?.name ?? "—"}</button></td><td className="px-4 py-5 text-[#344054]">{item.discount}折</td><td className="whitespace-nowrap px-4 py-5 text-[#667085]">{item.start} <span className="text-[#98a2b3]">至</span> {item.end}</td><td className="max-w-[310px] px-4 py-5 text-[#667085]"><div>课程属性：{item.attribute}</div><div>课程：{item.courses.join("、") || "—"}</div><div>班级：{item.classes.join("、") || "—"}</div></td><td className="max-w-[200px] px-4 py-5 text-[#667085]">{item.note || "—"}</td><td className="whitespace-nowrap px-4 py-5"><button onClick={() => toggleStudent(item.id)} className={item.status === "启用中" ? "mr-3 text-[#f04438]" : "mr-3 text-[#165dff]"}>{item.status === "启用中" ? "停用" : "启用"}</button><button onClick={() => setSelectedIdsForLog(item.id)} className="text-[#667085]">日志</button></td></tr>; })}</tbody></table>{!visibleStudents.length && <div className="px-6 py-16 text-center text-sm text-[#667085]">没有符合条件的学员</div>}</div>}</section></div>{ruleDrawer !== undefined && <RuleDrawer rule={ruleDrawer} onSave={saveRule} onClose={() => setRuleDrawer(undefined)} />}{studentDrawer !== undefined && <StudentDrawer student={studentDrawer} rules={rules} onSave={saveStudent} onClose={() => setStudentDrawer(undefined)} />}{detailRule && <DrawerShell title="优惠规则配置" onClose={() => setDetailRule(null)} footer={<button onClick={() => setDetailRule(null)} className="rounded-lg bg-[#18234b] px-5 py-2.5 text-sm font-semibold text-white">关闭</button>}><div className="space-y-4"><div className="rounded-xl bg-[#f8fafc] p-4"><p className="text-sm text-[#667085]">规则名称</p><p className="mt-1 text-lg font-semibold text-[#344054]">{detailRule.name}</p></div><div className="grid grid-cols-2 gap-4"><div className="rounded-xl border border-[#edf0f4] p-4"><p className="text-xs text-[#667085]">折扣比例</p><p className="mt-1 text-xl font-semibold text-[#165dff]">{detailRule.defaultDiscount}折</p></div><div className="rounded-xl border border-[#edf0f4] p-4"><p className="text-xs text-[#667085]">退费规则</p><p className="mt-1 text-sm font-medium text-[#344054]">{detailRule.refundRule}</p></div></div><div className="rounded-xl border border-[#edf0f4] p-4"><p className="text-sm font-semibold text-[#344054]">备注说明</p><p className="mt-2 text-sm leading-6 text-[#667085]">{detailRule.note || "暂无备注"}</p></div></div></DrawerShell>}</main>;
}
